// =========================================================================
// 🧭 ROUTE & PARSE INCOMING EVENT (Text, Voice Note, Callback, or Morning Cron)
// =========================================================================
const input = $input.first()?.json || {};
const DEFAULT_CHAT_ID = '1519369571'; // Serhat Kumas Telegram Chat ID

// 1. Scheduled 08:00 AM morning cron -> direct list_tasks
const isScheduled = Boolean(input.timestamp && !input.message && !input.callback_query);
if (isScheduled) {
  return [{
    json: {
      route: 'list_tasks',
      triggerSource: 'scheduled_morning',
      chatId: DEFAULT_CHAT_ID,
      isCallback: false,
      isMorningBriefing: true,
      todayFormatted: $now.setZone('Europe/Berlin').toFormat('EEEE, dd MMMM yyyy'),
      timeFormatted: $now.setZone('Europe/Berlin').toFormat('HH:mm')
    }
  }];
}

// 2. Telegram callback button click -> direct action
if (input.callback_query) {
  const cq = input.callback_query;
  const callbackId = cq.id;
  const data = cq.data || '';
  const chatId = String(cq.message?.chat?.id || cq.from?.id || DEFAULT_CHAT_ID);
  const messageId = cq.message?.message_id;
  const originalText = cq.message?.text || '';

  let route = 'help';
  let taskId = '';

  if (data.startsWith('done:')) {
    route = 'mark_done';
    taskId = data.substring(5);
  } else if (data.startsWith('del:')) {
    route = 'delete_task';
    taskId = data.substring(4);
  } else if (data === 'list' || data === 'refresh') {
    route = 'list_tasks';
  } else if (data === 'help') {
    route = 'help';
  }

  return [{
    json: {
      route,
      isCallback: true,
      callbackId,
      callbackData: data,
      taskId,
      chatId,
      messageId,
      originalText,
      triggerSource: 'telegram_callback',
      todayFormatted: $now.setZone('Europe/Berlin').toFormat('EEEE, dd MMMM yyyy'),
      timeFormatted: $now.setZone('Europe/Berlin').toFormat('HH:mm')
    }
  }];
}

// 3. Telegram Message: Text or Voice Note
const msg = input.message || {};
const chatId = String(msg.chat?.id || msg.from?.id || DEFAULT_CHAT_ID);

// 3a. Voice Note / Audio Message -> route to voice transcription
if (msg.voice || msg.audio) {
  const fileId = (msg.voice || msg.audio).file_id;
  return [{
    json: {
      route: 'voice_transcribe',
      fileId,
      chatId,
      isVoice: true,
      triggerSource: 'telegram_voice',
      todayFormatted: $now.setZone('Europe/Berlin').toFormat('EEEE, dd MMMM yyyy'),
      timeFormatted: $now.setZone('Europe/Berlin').toFormat('HH:mm')
    }
  }];
}

// 3b. Regular Text Message: Check fast-path vs AI evaluation
const text = (msg.text || '').trim();
let route = 'ai_eval';

if (/^\/(start|help)$/i.test(text)) {
  route = 'help';
} else if (/^\/(tasks|list|todo)$/i.test(text) || /^(tasks|list)$/i.test(text)) {
  route = 'list_tasks';
}

return [{
  json: {
    route,
    isCallback: false,
    chatId,
    rawText: text,
    taskTitle: text,
    triggerSource: 'telegram_message',
    todayFormatted: $now.setZone('Europe/Berlin').toFormat('EEEE, dd MMMM yyyy'),
    timeFormatted: $now.setZone('Europe/Berlin').toFormat('HH:mm')
  }
}];

// Read the actual bytes through n8n's storage-aware helper.
// $binary.data.data may be empty or a storage marker, not Base64.
const items = $input.all();
const output = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  if (!item.binary?.data) {
    throw new Error('No audio binary found in "data". Enable Download in Telegram: Download Voice File and run that node again.');
  }

  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
  if (!buffer.length) {
    throw new Error('Downloaded audio is empty. Download the Telegram voice file again before transcribing.');
  }

  output.push({
    json: {
      ...item.json,
      audioMimeType: item.binary.data.mimeType || 'audio/ogg',
      audioBase64: buffer.toString('base64'),
    },
    pairedItem: { item: i },
  });
}

return output;

