// =========================================================================
// 🎙️ EXTRACT TRANSCRIBED TEXT FROM GEMINI RESPONSE
// =========================================================================
const response = $input.first()?.json || {};
const transcribedText = response.candidates?.[0]?.content?.parts?.[0]?.text?.trim() || '';
const routeMeta = $('Route & Parse Event').first().json;
const chatId = routeMeta.chatId;
const timeFormatted = routeMeta.timeFormatted;

if (!transcribedText || transcribedText.length === 0) {
  return [{
    json: {
      action: 'help',
      chatId,
      rawText: 'help',
      timeFormatted,
      isVoice: true
    }
  }];
}

return [{
  json: {
    route: 'ai_eval',
    chatId,
    rawText: transcribedText,
    taskTitle: transcribedText,
    timeFormatted,
    isVoice: true
  }
}];

// =========================================================================
// 🧩 PARSE AI INTENT & SPLIT TASKS
// =========================================================================
const aiInput = $input.first()?.json || {};
const rawOutput = aiInput.output || aiInput.text || '';
const routeMeta = $('Route & Parse Event').first().json;
const chatId = routeMeta.chatId;
const timeFormatted = routeMeta.timeFormatted;
const fallbackTitle = routeMeta.rawText || routeMeta.taskTitle || 'New Task';

let action = 'create_task';
let tasks = [];

// Extract JSON block from AI output
const jsonMatch = rawOutput.match(/```(?:json)?\s*([\s\S]*?)\s*```/) || [null, rawOutput];
try {
  const parsed = JSON.parse(jsonMatch[1].trim());
  if (parsed && parsed.action) {
    action = parsed.action;
  }
  if (Array.isArray(parsed.tasks) && parsed.tasks.length > 0) {
    tasks = parsed.tasks.filter(t => t && t.title && t.title.trim().length > 0);
  }
} catch (e) {
  // Graceful keyword fallback if parsing fails:
  const lower = rawOutput.toLowerCase() + ' ' + fallbackTitle.toLowerCase();
  if (lower.includes('show') || lower.includes('list') || lower.includes('göster') || lower.includes('neler var')) {
    action = 'list_tasks';
  } else if (lower.includes('help') || lower.includes('yardım')) {
    action = 'help';
  } else {
    action = 'create_task';
    const lines = (fallbackTitle.includes(',') ? fallbackTitle.split(',') : fallbackTitle.split('\n'))
      .map(l => l.replace(/^[-*•\d.]+\s*/, '').trim())
      .filter(l => l.length > 0 && !l.startsWith('{') && !l.startsWith('['));
    tasks = lines.map(title => ({ title, notes: '' }));
  }
}

// Case 1: list_tasks intent
if (action === 'list_tasks') {
  return [{
    json: {
      action: 'list_tasks',
      chatId,
      timeFormatted
    }
  }];
}

// Case 2: help intent
if (action === 'help') {
  return [{
    json: {
      action: 'help',
      chatId,
      timeFormatted
    }
  }];
}

// Case 3: create_task intent
if (tasks.length === 0) {
  tasks = [{ title: fallbackTitle, notes: '' }];
}

return tasks.map(t => ({
  json: {
    action: 'create_task',
    chatId,
    taskTitle: t.title.trim(),
    notes: t.notes || 'Added via Telegram To-Do Bot',
    timeFormatted
  }
}));

// =========================================================================
// 🎨 FORMAT CREATED TASK CARD (iPhone Layout with Action Buttons)
// =========================================================================
const items = $input.all();
const routeMeta = $('Route & Parse Event').first().json;
const chatId = routeMeta.chatId;
const timeFormatted = routeMeta.timeFormatted;

return items.map(item => {
  const created = item.json;
  const title = created.title || 'Untitled Task';
  const taskId = created.id || '';

  let msg = `📌 <b>Task Added to Google Tasks</b>\n`;
  msg += `━━━━━━━━━━\n`;
  msg += `📝 <b>${title}</b>\n`;
  msg += `⏰ <i>Today • ${timeFormatted} (Berlin)</i>`;

  return {
    json: {
      chatId,
      taskId,
      title,
      messageText: msg
    }
  };
});

// =========================================================================
// ✏️ ASSEMBLE IN-PLACE MESSAGE UPDATE (Marked Done)
// =========================================================================
const routeMeta = $('Route & Parse Event').first().json;
const chatId = routeMeta.chatId;
const messageId = routeMeta.messageId;
const originalText = routeMeta.originalText || '';

const lines = originalText.split('\n').filter(l => l.trim().length > 0 && !l.includes('Tap below') && !l.includes('━'));
const taskTitleLine = lines.find(l => l.includes('📝') || l.match(/^[0-9]️⃣/)) || lines[0] || 'Task';
const cleanTaskTitle = taskTitleLine.replace(/^[0-9]️⃣\s*/, '').replace(/^📝\s*/, '').replace(/<[^>]+>/g, '').trim();

let updatedText = `✅ <b>Task Completed!</b>\n`;
updatedText += `━━━━━━━━━━\n`;
updatedText += `<s>${cleanTaskTitle}</s>\n`;
updatedText += `🎉 <i>Checked off in Google Tasks</i>`;

return [{
  json: {
    chatId,
    messageId,
    updatedText
  }
}];

// =========================================================================
// 🗑️ ASSEMBLE IN-PLACE MESSAGE UPDATE (Deleted Task)
// =========================================================================
const routeMeta = $('Route & Parse Event').first().json;
const chatId = routeMeta.chatId;
const messageId = routeMeta.messageId;
const originalText = routeMeta.originalText || '';

const lines = originalText.split('\n').filter(l => l.trim().length > 0 && !l.includes('Tap below') && !l.includes('━'));
const taskTitleLine = lines.find(l => l.includes('📝') || l.match(/^[0-9]️⃣/)) || lines[0] || 'Task';
const cleanTaskTitle = taskTitleLine.replace(/^[0-9]️⃣\s*/, '').replace(/^📝\s*/, '').replace(/<[^>]+>/g, '').trim();

let updatedText = `🗑️ <b>Task Deleted</b>\n`;
updatedText += `━━━━━━━━━━\n`;
updatedText += `<s>${cleanTaskTitle}</s>\n`;
updatedText += `👋 <i>Removed from Google Tasks</i>`;

return [{
  json: {
    chatId,
    messageId,
    updatedText
  }
}];

// =========================================================================
// 📱 FORMAT IPHONE TO-DO BRIEFING & TASK CARDS
// =========================================================================
const items = $input.all().map(item => item.json);
const routeMeta = $('Route & Parse Event').first().json;
const chatId = routeMeta.chatId || '1519369571';
const todayFormatted = routeMeta.todayFormatted || $now.setZone('Europe/Berlin').toFormat('EEEE, dd MMMM yyyy');
const timeFormatted = routeMeta.timeFormatted || $now.setZone('Europe/Berlin').toFormat('HH:mm');

// Filter valid active tasks (must have non-empty id and title)
const activeTasks = items.filter(t => t && t.id && t.status !== 'completed' && t.title && t.title.trim().length > 0);

if (activeTasks.length === 0) {
  let emptyMsg = `🎉 <b>All Clear! No Tasks To Do</b>\n`;
  emptyMsg += `━━━━━━━━━━\n\n`;
  emptyMsg += `You have no tasks to do right now! Enjoy your day. ✨\n\n`;
  emptyMsg += `💡 <i>To add a task, send text or voice:</i>\n`;
  emptyMsg += `<code>/add Prepare pitch deck</code>`;

  return [{
    json: {
      chatId,
      messageText: emptyMsg,
      taskId: '',
      isEmpty: true
    }
  }];
}

const numEmojis = ['1️⃣', '2️⃣', '3️⃣', '4️⃣', '5️⃣', '6️⃣', '7️⃣', '8️⃣', '9️⃣', '🔟'];

return activeTasks.map((task, index) => {
  const emoji = numEmojis[index] || `[${index + 1}]`;
  const cleanTitle = task.title.trim();
  let text = `${emoji} <b>${cleanTitle}</b>\n`;
  text += `⏰ <i>Google Tasks • Active</i>`;

  return {
    json: {
      chatId,
      messageText: text,
      taskId: task.id,
      taskTitle: cleanTitle,
      index: index + 1,
      isEmpty: false
    }
  };
});
